package edu.fuzzy;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.*;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.security.access.AccessDeniedException;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:workflows;MODE=MySQL;DB_CLOSE_DELAY=-1","fuzzy.data-root=target/test-runtime","fuzzy.demo=true"})
@ActiveProfiles("demo") @AutoConfigureMockMvc
class WorkflowIntegrationTest {
 @Autowired MockMvc mvc;@Autowired Db db;@Autowired AccountService accounts;@Autowired WorkflowService flow;@Autowired CryptoService crypto;
 Map<String,Object> alice(){return db.user("alice@demo.local");}Map<String,Object> bob(){return db.user("bob@demo.local");}Map<String,Object> kgc(){return db.user("kgc@demo.local");}Map<String,Object> tpa(){return db.user("tpa@demo.local");}Map<String,Object> cloud(){return db.user("cloud@demo.local");}
 String upload(String name,byte[]bytes)throws Exception{return flow.upload(alice(),new MockMultipartFile("file",name,"application/octet-stream",bytes),"");}
 @Test void registrationApprovalRejectionProfileAndSignature()throws Exception{
  String email="new-"+Db.id()+"@demo.local";var form=new HashMap<String,String>(Map.of("name","Synthetic Test","email",email,"password","Test@123456","dob","2002-01-02","gender","Female","phone","0000000000","city","Demo City","country","Demo Country"));form.put("rpassword","Test@123456");String id=accounts.register(form,null);var u=db.user(email);assertEquals("PENDING",u.get("approval"));assertEquals("2002-01-02",u.get("dob"));assertThrows(AccessDeniedException.class,()->flow.upload(u,new MockMultipartFile("file","a.txt","text/plain",new byte[]{1}),""));assertThrows(AccessDeniedException.class,()->accounts.decide(bob(),id,true));accounts.decide(kgc(),id,true);assertEquals("APPROVED",db.user(email).get("approval"));assertFalse(Db.str(db.user(email),"wrapped_identity_key").isBlank());assertThrows(IllegalArgumentException.class,()->accounts.register(form,null));form.put("email","rejected-"+Db.id()+"@demo.local");String rejected=accounts.register(form,null);accounts.decide(kgc(),rejected,false);assertEquals("REJECTED",db.one("select * from app_user where id=?",rejected).get("approval"));
 }
 @Test void sharingOwnershipDenyApproveRejectAndRevoke()throws Exception{
  byte[]bytes={0,1,2,13,10,-1,0};String id=upload("binary.bin",bytes);assertArrayEquals(bytes,flow.download(alice(),id));assertThrows(AccessDeniedException.class,()->flow.download(bob(),id));flow.requestAccess(bob(),id);assertThrows(IllegalArgumentException.class,()->flow.requestAccess(bob(),id));String r=Db.str(db.one("select * from share_request where file_id=?",id),"id");assertThrows(AccessDeniedException.class,()->flow.decideShare(bob(),r,"APPROVED"));flow.decideShare(alice(),r,"APPROVED");assertArrayEquals(bytes,flow.download(bob(),id));flow.decideShare(alice(),r,"REVOKED");assertThrows(AccessDeniedException.class,()->flow.download(bob(),id));String id2=upload("binary.bin",bytes);assertNotEquals(id,id2);flow.requestAccess(bob(),id2);String r2=Db.str(db.one("select * from share_request where file_id=?",id2),"id");flow.decideShare(alice(),r2,"REJECTED");assertThrows(AccessDeniedException.class,()->flow.download(bob(),id2));assertThrows(AccessDeniedException.class,()->flow.requestAudit(bob(),id,"FULL"));assertThrows(AccessDeniedException.class,()->flow.download(cloud(),id));
 }
 @Test void auditPassReplayTamperBaselineStableAndRecovery()throws Exception{
  String id=upload("audit.bin",new byte[150000]);String baseline=Db.str(flow.file(id),"manifest_json");String a=flow.requestAudit(alice(),id,"FULL");assertThrows(AccessDeniedException.class,()->flow.challenge(cloud(),a));flow.challenge(tpa(),a);assertThrows(IllegalArgumentException.class,()->flow.challenge(tpa(),a));flow.respond(cloud(),a);flow.verify(tpa(),a);assertEquals("VERIFIED_PASS",flow.audit(alice(),a).get("audit_state"));assertThrows(IllegalArgumentException.class,()->flow.verify(tpa(),a));flow.tamper(cloud(),id,0);assertEquals(baseline,flow.file(id).get("manifest_json"));String bad=flow.requestAudit(alice(),id,"FULL");flow.challenge(tpa(),bad);flow.respond(cloud(),bad);flow.verify(tpa(),bad);assertEquals("VERIFIED_FAIL",flow.audit(alice(),bad).get("audit_state"));assertThrows(IllegalArgumentException.class,()->flow.download(alice(),id));String recovered=flow.upload(alice(),new MockMultipartFile("file","audit.bin","application/octet-stream",new byte[150000]),id);assertEquals(2,Db.num(flow.file(recovered),"file_version"));assertEquals("VERIFIED_FAIL",flow.audit(alice(),bad).get("audit_state"));assertArrayEquals(new byte[150000],flow.download(alice(),recovered));
 }
 @Test void missingTruncatedObjectsAndExpiredChallenge()throws Exception{
  String id=upload("missing.bin",new byte[140000]);String a=flow.requestAudit(alice(),id,"FULL");flow.challenge(tpa(),a);Files.delete(crypto.object(id));flow.respond(cloud(),a);assertEquals("ERROR",flow.audit(alice(),a).get("audit_state"));assertThrows(IllegalArgumentException.class,()->flow.download(alice(),id));String truncated=upload("truncated.bin",new byte[140000]);Files.write(crypto.object(truncated),new byte[10]);String b=flow.requestAudit(alice(),truncated,"FULL");flow.challenge(tpa(),b);flow.respond(cloud(),b);flow.verify(tpa(),b);assertEquals("VERIFIED_FAIL",flow.audit(alice(),b).get("audit_state"));String expired=upload("expired.bin",new byte[2]);String c=flow.requestAudit(alice(),expired,"FULL");flow.challenge(tpa(),c);String old=Db.str(flow.audit(tpa(),c),"challenge_json");String altered=old.replaceAll("\"expiresAt\":\\d+","\"expiresAt\":1");db.jdbc.update("update audit_record set challenge_json=? where id=?",altered,c);flow.respond(cloud(),c);assertEquals("EXPIRED",flow.audit(tpa(),c).get("audit_state"));
 }
 @Test void invalidUploadsAndManifestChecksumGuard()throws Exception{assertThrows(IllegalArgumentException.class,()->upload("../escape.txt",new byte[]{1}));assertThrows(IllegalArgumentException.class,()->upload("empty.txt",new byte[0]));assertThrows(IllegalArgumentException.class,()->upload("huge.bin",new byte[10485761]));String id=upload("manifest.txt",new byte[]{1});db.jdbc.update("update stored_file set manifest_checksum='wrong' where id=?",id);assertThrows(IllegalStateException.class,()->flow.manifest(flow.file(id)));}
 @Test void anonymousCsrfPasswordOtpAndLogout()throws Exception{
  mvc.perform(get("/dashboard")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/login"));mvc.perform(post("/login").param("email","alice@demo.local").param("password","Demo@12345")).andExpect(status().isForbidden());mvc.perform(post("/login").with(csrf()).param("email","alice@demo.local").param("password","bad")).andExpect(redirectedUrl("/login"));
  var login=mvc.perform(post("/login").with(csrf()).param("email","alice@demo.local").param("password","Demo@12345")).andExpect(redirectedUrl("/otp")).andReturn();MockHttpSession session=(MockHttpSession)login.getRequest().getSession();mvc.perform(get("/dashboard").session(session)).andExpect(redirectedUrl("/login"));var state=(OtpService.State)session.getAttribute("otp");mvc.perform(post("/otp").with(csrf()).session(session).param("code","bad")).andExpect(status().isBadRequest());mvc.perform(post("/otp").with(csrf()).session(session).param("code",state.code)).andExpect(redirectedUrl("/dashboard"));mvc.perform(get("/dashboard").session(session)).andExpect(status().isOk());mvc.perform(post("/logout").with(csrf()).session(session)).andExpect(redirectedUrl("/login?logout"));assertTrue(session.isInvalid());
 }
 @Test @WithMockUser(username="bob@demo.local",roles="USER")void roleOwnershipFuzzyAndThresholdTampering()throws Exception{
  String id=upload("protected.bin",new byte[]{1,2});mvc.perform(post("/kgc/users/x/decide").with(csrf()).param("decision","APPROVED")).andExpect(status().isForbidden());mvc.perform(post("/cloud/files/"+id+"/tamper").with(csrf()).param("block","0")).andExpect(status().isForbidden());mvc.perform(get("/user/files/"+id+"/download")).andExpect(status().isForbidden());
  MockHttpSession s=new MockHttpSession();mvc.perform(post("/user/fuzzy").session(s).with(csrf()).param("attributes","11,22,33,44,55").param("threshold","1").param("success","true")).andExpect(status().isOk()).andExpect(model().attribute("fuzzyValid",false));mvc.perform(post("/user/fuzzy").session(s).with(csrf()).param("attributes","11,22,33,44,55,66")).andExpect(status().isOk()).andExpect(model().attribute("fuzzyValid",true));mvc.perform(get("/user/files/"+id+"/download").session(s)).andExpect(status().isForbidden());mvc.perform(post("/user/files/"+id+"/audit").session(s).with(csrf()).param("mode","FULL")).andExpect(status().isForbidden());s.setAttribute("fuzzyUntil",1L);mvc.perform(multipart("/user/upload").file(new MockMultipartFile("file","x.txt","text/plain",new byte[]{1})).session(s).with(csrf())).andExpect(status().isForbidden());
 }
}
